select u.user_id, u.dept_id, u.user_name, u.nick_name, u.user_type, u.tenant_key, u.email, u.phone_number, u.password, u.sex, u.id_card,
u.status, u.del_flag, u.super_flag, u.login_ip, u.login_date, u.create_user, u.create_time, u.remark, u.pt_var_1, u.pt_var_2, u.pt_var_3, u.pt_var_4, u.pt_var_5
FROM
sys_user u,
(select user_id from sys_user_role sur,sys_role sr where sur.role_id = sr.role_id

     and sur.tenant_key = #{tenantKey}

 and sur.role_id = sr.role_id and sr.role_key in

